/* Column layout */
column-set {
    display: flex;
    flex-wrap: wrap;
    gap: 1.3rem;
    align-items: flex-start; /* ensures all columns start at the same top line */
	position: relative;
    top: 0.3rem;  /* moves the block upward */
}


/* Column widths (based on 12-column span) */
column-unit[slot="0"] { flex: 0 0 39; }
column-unit[slot="1"] { flex: 0 0 25%; }
column-unit[slot="2"] { flex: 0 0 25%; }

/* Make columns stack on small screens */
@media screen and (max-width: 768px) {
    column-set {
        flex-direction: column;
    }
    column-unit {
        flex: 0 0 100%;
    }
}

h2 {
    font-size: 1.45rem;      /* unified size */
    line-height: 1.6;     /* consistent spacing */
    color: #ffffff;
    margin: 0 0 0.3rem 0; /* minimal spacing below */
}

/* Paragraphs */
p {
    font-size: 1.0rem;      /* unified size */
    line-height: 1.25;     /* consistent spacing */
    color: #d1d1d1;
    margin: 0 0 0.5rem 0; /* minimal spacing between lines */
}

/* General text styling */
.about-me {
    color: white;
    text-align: left;
    line-height: 1.1;
    width: 94%;
    font-size: 1rem;

    position: relative;
    top: -2.25rem;  /* moves the block upward */
}


.contactme-mobile {
    color: white;
    text-align: left;
    line-height: 1.0;
    font-size: 1rem;
    width: 100%;
    margin-top: -30px;

}

/* Address styling */
.address-wrapper {
    text-align: left;
top: -1rem;
}

.address p {
    margin: 0.5rem 0;
    line-height: 1.0;
    position: relative;
    top: -0.rem;  /* moves the block upward */

}

.address a {
    position: relative;
    display: inline-block;
    width: fit-content;
    color: #d1d1d1;
    text-decoration: none;
    font-size: 1.25rem;
    transition: color 0.3s ease;
}

/* Animated underline */
.address a::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -1px;              /* adjust closeness here */
    width: 100%;
    height: 1.5px;
    background-color: #d1d1d1;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s ease;
}

/* Hover */
.address a:hover {
    color: white;
}

.address a:hover::after {
    transform: scaleX(1);
}


/* Images and media-items responsive */
img, media-item {
    width: 100%;
    height: auto;
    display: block;
}

.about-text p{
    color: #d1d1d1;
    line-height: 1.3;
    font-size: 1.2rem;
    margin-top: 0rem;
    margin-bottom: 0.25rem;
         /* makes both left and right edges aligned */
    text-justify: inter-word;     /* spreads words evenly */
    hyphens: auto;                /* allows automatic word hyphenation for better fit */

}


.clients {
    line-height:1.45;
	font-size: 1.2rem;
    position: relative;
    top: -0.2rem;  /* moves the block upward */
}
